using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using AdMng.App.Controls;
using AdMng.App.UiTests.Infrastructure;
using AdMng.Presentation.Icons;

namespace AdMng.App.UiTests;

/// <summary>
/// The icon set (Themes/Icons.xaml, generated by tools/icon/build-icon-set.py from docs/assets/icons): every key of
/// <see cref="AppIcons"/> is a frozen <see cref="DrawingImage"/> of 48 x 48 units in the application resources, every
/// <see cref="ObjectIcon"/> has its picture, and each picture really paints something at 16 and at 48 pixels.
/// </summary>
[Collection(UiTestCollection.Name)]
public sealed class IconSetTests
{
    private const double Size = 48;

    [Fact]
    public Task EveryKey_IsADrawingImageOf48By48Units() => WpfTestHost.RunAsync(() =>
    {
        Assert.True(AppIcons.All.Count >= 60, $"only {AppIcons.All.Count} icons");
        Assert.Equal(AppIcons.All.Count, AppIcons.All.Distinct(StringComparer.Ordinal).Count());
        foreach (var key in AppIcons.All)
        {
            Assert.StartsWith("Icon.", key, StringComparison.Ordinal);
            var image = Assert.IsType<DrawingImage>(AppIcons.Find(key));
            Assert.True(image.IsFrozen, $"{key} is not frozen");
            var bounds = image.Drawing.Bounds;
            Assert.True(
                Math.Abs(bounds.X) < 0.01 && Math.Abs(bounds.Y) < 0.01 && Math.Abs(bounds.Width - Size) < 0.01 && Math.Abs(bounds.Height - Size) < 0.01,
                $"{key}: the drawing bounds are {bounds}, not 0,0,48,48");
            Assert.Equal(Size, image.Width, 2);
            Assert.Equal(Size, image.Height, 2);
        }

        return Task.CompletedTask;
    });

    [Fact]
    public Task Constants_List_AndDictionary_NameTheSameIcons() => WpfTestHost.RunAsync(() =>
    {
        var constants = typeof(AppIcons).GetFields(BindingFlags.Public | BindingFlags.Static)
            .Where(field => field.IsLiteral && field.FieldType == typeof(string))
            .Select(field => (Name: field.Name, Key: (string)field.GetRawConstantValue()!))
            .ToList();

        Assert.All(constants, constant => Assert.Equal("Icon." + constant.Name, constant.Key));
        Assert.Equal(AppIcons.All.Order(StringComparer.Ordinal).ToArray(), constants.Select(c => c.Key).Order(StringComparer.Ordinal).ToArray());

        // The generated dictionary holds exactly these keys (a stale AppIcons.cs or Icons.xaml fails here).
        var dictionary = Assert.Single(
            Application.Current.Resources.MergedDictionaries,
            d => d.Source is not null && d.Source.OriginalString.EndsWith("Themes/Icons.xaml", StringComparison.OrdinalIgnoreCase));
        Assert.Equal(AppIcons.All.Order(StringComparer.Ordinal).ToArray(), dictionary.Keys.OfType<string>().Order(StringComparer.Ordinal).ToArray());
        Assert.Null(AppIcons.Find("Icon.NoSuchIcon"));
        return Task.CompletedTask;
    });

    [Fact]
    public Task EveryObjectIcon_HasItsOwnPicture() => WpfTestHost.RunAsync(() =>
    {
        var values = Enum.GetValues<ObjectIcon>();
        foreach (var icon in values)
        {
            var key = AppIcons.KeyFor(icon);
            Assert.Equal("Icon." + icon, key);
            Assert.Contains(key, AppIcons.All);
            Assert.IsType<DrawingImage>(AppIcons.Find(key));
        }

        Assert.Equal(values.Length, values.Select(AppIcons.KeyFor).Distinct(StringComparer.Ordinal).Count());
        // A value outside the enum falls back to the neutral picture instead of throwing.
        Assert.Equal(AppIcons.Unknown, AppIcons.KeyFor((ObjectIcon)(-1)));
        return Task.CompletedTask;
    });

    [Theory]
    [InlineData(16)]
    [InlineData(48)]
    public Task EveryIcon_PaintsASensibleShareOfItsPixels(int pixels) => WpfTestHost.RunAsync(() =>
    {
        var problems = new List<string>();
        foreach (var key in AppIcons.All)
        {
            var alpha = RenderAlpha(Assert.IsType<DrawingImage>(AppIcons.Find(key)), pixels);
            var painted = alpha.Count(a => a > 32) / (double)alpha.Length;
            // The smallest pictures are the overlays (one quadrant, about 14 % of the canvas), the fullest the tiles
            // (40 of 48 units squared, about 70 %): an empty, clipped or fully covered picture is outside 6 .. 90 %.
            if (painted is < 0.06 or > 0.90)
            {
                problems.Add($"{key} at {pixels} px paints {painted:P1} of the pixels");
            }

            // Nothing is drawn in the safe margin (2 of 48 units), so the outermost pixel ring stays empty at 48 px.
            if (pixels == (int)Size)
            {
                var edge = Enumerable.Range(0, pixels).SelectMany(i => new[]
                {
                    alpha[i], alpha[((pixels - 1) * pixels) + i], alpha[i * pixels], alpha[(i * pixels) + pixels - 1],
                }).Max();
                if (edge > 32)
                {
                    problems.Add($"{key} paints into the outermost pixel ring (alpha {edge})");
                }
            }
        }

        Assert.Empty(problems);
        return Task.CompletedTask;
    });

    /// <summary>The alpha channel of the image shown by an <see cref="Image"/> of pixels x pixels (96 DPI).</summary>
    private static byte[] RenderAlpha(ImageSource source, int pixels)
    {
        var image = new Image { Source = source, Width = pixels, Height = pixels, Stretch = Stretch.Uniform };
        image.Measure(new Size(pixels, pixels));
        image.Arrange(new Rect(0, 0, pixels, pixels));
        image.UpdateLayout();
        var bitmap = new RenderTargetBitmap(pixels, pixels, 96, 96, PixelFormats.Pbgra32);
        bitmap.Render(image);
        var buffer = new byte[pixels * pixels * 4];
        bitmap.CopyPixels(buffer, pixels * 4, 0);
        var alpha = new byte[pixels * pixels];
        for (var i = 0; i < alpha.Length; i++)
        {
            alpha[i] = buffer[(i * 4) + 3];
        }

        return alpha;
    }
}
